import{_ as o,o as r,c as n,ag as a}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"神经科学","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/neuroscience/index.md","filePath":"topics/neuroscience/index.md"}'),e={name:"topics/neuroscience/index.md"};function s(i,t,u,l,h,d){return r(),n("div",null,[...t[0]||(t[0]=[a(`<h1 id="神经科学" tabindex="-1">神经科学 <a class="header-anchor" href="#神经科学" aria-label="Permalink to &quot;神经科学&quot;">​</a></h1><blockquote><p>神经科学不只是关于大脑——它是关于<strong>身体如何参与思维、感知如何塑造现实、意识如何从物质中涌现</strong>。本主题的核心立场是：<strong>身体不是大脑的执行器，而是思维系统的组成部分。</strong></p></blockquote><hr><h2 id="一、核心命题-具身认知——这个主题的统一框架" tabindex="-1">一、核心命题：具身认知——这个主题的统一框架 <a class="header-anchor" href="#一、核心命题-具身认知——这个主题的统一框架" aria-label="Permalink to &quot;一、核心命题：具身认知——这个主题的统一框架&quot;">​</a></h2><h3 id="为什么传统神经科学是-半个科学" tabindex="-1">为什么传统神经科学是&quot;半个科学&quot; <a class="header-anchor" href="#为什么传统神经科学是-半个科学" aria-label="Permalink to &quot;为什么传统神经科学是&quot;半个科学&quot;&quot;">​</a></h3><p>传统神经科学（20 世纪后半叶的主流范式）有一个隐含假设：大脑是&quot;中央处理器&quot;，身体是&quot;输入输出设备&quot;。大脑接收感官信号，做计算，输出运动指令。这个假设在实验室里很方便（你可以把大脑切片、扫描、建模），但它割裂了大脑和身体之间本质上的双向关系。</p><p><strong>具身认知（Embodied Cognition）</strong> 范式纠正了这一点。它的核心观点：</p><ol><li><strong>认知不是发生在大脑里，而是发生在&quot;大脑-身体-环境&quot;的耦合系统中。</strong></li><li><strong>身体状态直接影响认知状态。</strong> 呼吸频率改变决策倾向，姿势改变自信水平，肠道微生物改变情绪。</li><li><strong>记忆不是&quot;调取&quot;，是&quot;重演&quot;。</strong> 回忆一个场景时，眼球会按照最初观看时的路径重新移动——眼球不是回忆的副产品，而是回忆的脚手架。</li></ol><h3 id="这个主题的五份文档-从五个角度论证同一个命题" tabindex="-1">这个主题的五份文档，从五个角度论证同一个命题 <a class="header-anchor" href="#这个主题的五份文档-从五个角度论证同一个命题" aria-label="Permalink to &quot;这个主题的五份文档，从五个角度论证同一个命题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>呼吸 → 大脑 → 决策（breathing-brain-decision）</span></span>
<span class="line"><span>眼球 → 记忆 → 大脑（eye-fixation-scanpath）</span></span>
<span class="line"><span>身体 → 意识 → 能量（xingyiquan-complete-system）</span></span>
<span class="line"><span>基因 → 生物技术 → 治疗（biotech-frontier）</span></span>
<span class="line"><span>大脑 → 机器 → 通信（brain-computer-interface-deep）</span></span></code></pre></div><p>它们共同拼出了&quot;具身认知&quot;的全景：<strong>从呼吸到眼球，从基因到机器，身体的每一层都在参与&quot;我们是谁&quot;的构建。</strong></p><hr><h2 id="二、五大知识模块" tabindex="-1">二、五大知识模块 <a class="header-anchor" href="#二、五大知识模块" aria-label="Permalink to &quot;二、五大知识模块&quot;">​</a></h2><h3 id="模块一-呼吸-大脑-决策三通路" tabindex="-1">模块一：呼吸-大脑-决策三通路 <a class="header-anchor" href="#模块一-呼吸-大脑-决策三通路" aria-label="Permalink to &quot;模块一：呼吸-大脑-决策三通路&quot;">​</a></h3><p><strong>核心文件</strong>：<a href="/zhishiku-reading/topics/neuroscience/breathing-brain-decision.html">呼吸-大脑-决策：内家拳与神经科学的跨时空对话</a></p><p><strong>核心问题</strong>：为什么&quot;深呼吸能让你冷静&quot;？这不是心理暗示，而是三条精确的神经通路。</p><p><strong>三通路模型</strong>：</p><table tabindex="0"><thead><tr><th>通路</th><th>解剖路径</th><th>作用</th><th>时间尺度</th></tr></thead><tbody><tr><td>迷走神经（Vagal afferent）</td><td>肺 → 孤束核 → 蓝斑 → 前额叶</td><td>慢呼吸激活迷走神经传入纤维，抑制杏仁核活动，降低焦虑</td><td>秒级</td></tr><tr><td>嗅球（Olfactory bulb）</td><td>鼻腔气流 → 嗅球 → 海马体</td><td>鼻呼吸的节律性气流直接耦合到嗅球振荡，而嗅球与海马体的 theta 振荡同步——海马体是记忆和情绪调节的核心</td><td>毫秒级</td></tr><tr><td>压力反射（Baroreflex）</td><td>主动脉弓/颈动脉窦 → 延髓 → 自主神经输出</td><td>慢呼吸在每个呼吸周期中产生血压波动，压力反射将波动转化为自主神经的节律性调节（心率变异性增加 = 副交感神经活性增强）</td><td>秒级</td></tr></tbody></table><p><strong>关键洞察</strong>：这三条通路都指向同一个结论——<strong>呼吸不是&quot;大脑指令的执行&quot;，而是&quot;大脑状态的输入&quot;</strong>。你不需要&quot;控制情绪&quot;来改变呼吸，你只需要改变呼吸来改变情绪。这是具身认知最精确的生物学证据。</p><p><strong>与内家拳的对应</strong>：形意拳的&quot;逆腹式呼吸&quot;、太极拳的&quot;气沉丹田&quot;、瑜伽的 Pranayama——这些千年实践，本质上是在精确操控这三条通路。慢呼吸的核心不是&quot;吸更多氧&quot;，而是<strong>调整呼气/吸气比值</strong>，将自主神经推向副交感主导的状态。</p><hr><h3 id="模块二-眼球固定法——scanpath-理论与具身记忆" tabindex="-1">模块二：眼球固定法——scanpath 理论与具身记忆 <a class="header-anchor" href="#模块二-眼球固定法——scanpath-理论与具身记忆" aria-label="Permalink to &quot;模块二：眼球固定法——scanpath 理论与具身记忆&quot;">​</a></h3><p><strong>核心文件</strong>：<a href="/zhishiku-reading/topics/neuroscience/eye-fixation-scanpath.html">眼球固定法：scanpath 理论与具身记忆</a></p><p><strong>核心问题</strong>：为什么&quot;眼球不动&quot;能阻止焦虑回忆？</p><p><strong>Scanpath 理论</strong>（Stark &amp; Norton, 1971）：当人回忆一个视觉场景时，眼球会按照和最初观看时<strong>几乎相同的路径</strong>移动。回忆不是大脑里放一张静态图片——它是大脑<strong>重新执行</strong>当初的观看过程，眼球也参与其中。</p><p><strong>神经回路</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主动回忆 → 额叶眼动区（FEF）发出检索指令 → 海马体调取空间索引 → 上丘指挥眼球重演扫描路径</span></span></code></pre></div><p><strong>关键</strong>：这个回路不是单向的。上丘在指挥眼动的同时，向视觉皮层发送&quot;空间更新&quot;确认信号。如果眼动被阻断，空间更新信号丢失，海马体的检索过程被中断。</p><p><strong>实操</strong>：固定眼球 30 秒-2 分钟 → 上丘不发送空间更新 → FEF 不向海马体发送检索指令 → 回忆线程被中断 → 反刍循环停止。</p><p><strong>与 EMDR 的对照</strong>：EMDR（眼动脱敏与再加工）用的是<strong>相反</strong>的策略——刻意引导眼动来&quot;改写&quot;创伤记忆。原理是：眼动占用视觉-空间工作记忆资源，使创伤记忆在同时回忆时&quot;降级&quot;为低分辨率版本。一个锁门（固定眼球），一个擦字（EMDR 眼动），同一个锁的不同钥匙方向。</p><p><strong>深层含义</strong>：这个发现的意义远超&quot;焦虑小技巧&quot;。它证明了<strong>记忆不是&quot;调取&quot;而是&quot;重演&quot;</strong>——身体是记忆系统的一部分，不是附属品。</p><hr><h3 id="模块三-形意拳——身体作为意识的引擎" tabindex="-1">模块三：形意拳——身体作为意识的引擎 <a class="header-anchor" href="#模块三-形意拳——身体作为意识的引擎" aria-label="Permalink to &quot;模块三：形意拳——身体作为意识的引擎&quot;">​</a></h3><p><strong>核心文件</strong>：<a href="/zhishiku-reading/topics/neuroscience/xingyiquan-complete-system.html">形意拳完整体系</a></p><p><strong>核心问题</strong>：为什么一套 300 年前的拳法，在现代神经科学框架下展现出惊人的精确性？</p><p><strong>形意拳的本质</strong>：不是&quot;格斗技术&quot;，而是<strong>身体意识的训练系统</strong>。它的每一个训练环节（三体式站桩、五行拳、十二形）都在训练同一个能力：<strong>用身体感知和调节神经系统状态</strong>。</p><p><strong>六合（内外三合）</strong>：肩与胯合、肘与膝合、手与足合（外三合）；心与意合、意与气合、气与力合（内三合）。这不是玄学，而是<strong>本体感觉的精确对齐</strong>。当外三合对齐，身体的重心、力矩、发力链都被优化，神经系统接收到的本体感觉信号是&quot;有序&quot;的——这种有序信号本身就能降低焦虑水平（因为焦虑的神经基础之一就是&quot;身体感觉的混乱&quot;）。</p><p><strong>三层功夫</strong>：明劲（练骨）→ 暗劲（练筋）→ 化劲（练髓）。这不是武术等级的划分，而是<strong>神经系统对身体控制精度的三个阶段</strong>：粗大运动控制 → 精细运动控制 → 全身协调的&quot;无意识&quot;控制。</p><p><strong>与模块一、二的呼应</strong>：</p><ul><li>形意拳的呼吸法（逆腹式呼吸）→ 对应模块一的迷走神经通路</li><li>形意拳的&quot;眼随手走&quot;→ 对应模块二的 scanpath 理论（眼球运动与注意力的耦合）</li><li>形意拳的站桩 → 对应自主神经的调节训练</li></ul><p><strong>结论</strong>：形意拳是一个&quot;前科学时代的具身认知实验&quot;。它没有神经科学的术语，但它的训练体系精确地对应了现代神经科学发现的&quot;身体如何参与思维&quot;的机制。</p><hr><h3 id="模块四-生物技术前沿——从基因到意识的干预" tabindex="-1">模块四：生物技术前沿——从基因到意识的干预 <a class="header-anchor" href="#模块四-生物技术前沿——从基因到意识的干预" aria-label="Permalink to &quot;模块四：生物技术前沿——从基因到意识的干预&quot;">​</a></h3><p><strong>核心文件</strong>：<a href="/zhishiku-reading/topics/neuroscience/biotech-frontier.html">生物技术前沿深度</a></p><p><strong>核心问题</strong>：当我们可以编辑基因、重编程细胞、延长寿命，神经科学的下一个边界在哪里？</p><p><strong>五大前沿</strong>：</p><ol><li><p><strong>CRISPR 三代进化</strong>：从 Cas9（切割 DNA）到碱基编辑（单个碱基替换）到先导编辑（搜索+替换任意序列）。对神经科学的含义：遗传性神经疾病（亨廷顿舞蹈症、ALS）的根治从&quot;不可能&quot;变成&quot;工程问题&quot;。</p></li><li><p><strong>表观遗传编辑</strong>：不改变 DNA 序列，而是改变基因的&quot;开关&quot;状态。这意味着：我们可以通过环境干预（饮食、运动、压力管理）来&quot;编程&quot;基因表达——生活方式不是&quot;软科学&quot;，而是精确的分子生物学。</p></li><li><p><strong>抗衰老</strong>：Senolytics（清除衰老细胞）、NAD+ 补充、表观遗传时钟逆转。对神经科学的意义：阿尔茨海默病和帕金森病的最大风险因子是年龄。如果衰老本身可以被延缓，神经退行性疾病的发病率将断崖式下降。</p></li><li><p><strong>mRNA 平台</strong>：COVID 疫苗只是开始。个性化癌症疫苗、mRNA 编码的神经生长因子、mRNA 介导的神经再生——这些都在临床试验中。</p></li><li><p><strong>AI + 生物</strong>：AlphaFold 3 预测所有生物分子的结构和相互作用。这意味着药物发现从&quot;试错&quot;变成&quot;设计&quot;——AI 可以预测一个分子是否会穿过血脑屏障、是否与特定受体结合、是否会产生毒性。</p></li></ol><hr><h3 id="模块五-脑机接口——大脑与机器的直接对话" tabindex="-1">模块五：脑机接口——大脑与机器的直接对话 <a class="header-anchor" href="#模块五-脑机接口——大脑与机器的直接对话" aria-label="Permalink to &quot;模块五：脑机接口——大脑与机器的直接对话&quot;">​</a></h3><p><strong>核心文件</strong>：<a href="/zhishiku-reading/topics/neuroscience/brain-computer-interface-deep.html">脑机接口与 6G 深度</a></p><p><strong>核心问题</strong>：当大脑可以直接和机器对话，人类和工具的边界在哪里？</p><p><strong>侵入式 vs 非侵入式的权衡</strong>：</p><ul><li>侵入式（Neuralink、Utah Array）：信号质量高（单个神经元级别），但需要开颅手术，存在感染和免疫排斥风险</li><li>非侵入式（EEG、fNIRS）：无手术风险，但信号噪声大，空间分辨率低（只能定位到厘米级脑区）</li><li>半侵入式（ECoG）：放在硬脑膜上，不穿透脑组织，信号质量介于两者之间</li></ul><p><strong>神经解码的数学</strong>：脑机接口的核心不是&quot;读心术&quot;，而是<strong>解码</strong>——从神经信号中提取意图。这是一个典型的信号处理问题：从高维、噪声大、非平稳的神经信号中，解码出低维的运动意图（&quot;我想移动光标到 X 方向&quot;）。常用的方法：卡尔曼滤波、递归神经网络（RNN）、脉冲神经网络（SNN）。</p><p><strong>6G 的角色</strong>：如果脑机接口要进入消费级市场，带宽是关键瓶颈。单个神经元 1kHz 采样 × 1000 个通道 = 1Mbps 的原始数据。如果扩展到 100 万个通道（接近大脑皮层表面），就是 1Gbps。6G 的太赫兹频段和空天地海一体化网络，为&quot;云端大脑&quot;提供了物理基础。</p><p><strong>伦理边界</strong>：当大脑可以直接和机器对话，&quot;思想&quot;是否还属于自己？&quot;神经隐私&quot;（neural privacy）是下一个前沿——你的大脑信号包含了比你愿意分享的更多的信息（情绪状态、注意力水平、潜意识偏好）。</p><hr><h2 id="三、跨模块规律" tabindex="-1">三、跨模块规律 <a class="header-anchor" href="#三、跨模块规律" aria-label="Permalink to &quot;三、跨模块规律&quot;">​</a></h2><h3 id="规律一-身体是思维的-硬件加速器" tabindex="-1">规律一：身体是思维的&quot;硬件加速器&quot; <a class="header-anchor" href="#规律一-身体是思维的-硬件加速器" aria-label="Permalink to &quot;规律一：身体是思维的&quot;硬件加速器&quot;&quot;">​</a></h3><p>五个模块反复验证同一个命题：<strong>身体不是大脑的附属品，而是思维的硬件加速器。</strong> 呼吸改变决策质量（模块一），眼球固定中断回忆（模块二），身体对齐优化神经系统状态（模块三），基因编辑改变认知能力（模块四），脑机接口扩展认知边界（模块五）。从分子到行为，从基因到机器，每一个层面都在说同一件事：<strong>思维是全身的事。</strong></p><h3 id="规律二-自下而上的干预比自上而下更有效" tabindex="-1">规律二：自下而上的干预比自上而下更有效 <a class="header-anchor" href="#规律二-自下而上的干预比自上而下更有效" aria-label="Permalink to &quot;规律二：自下而上的干预比自上而下更有效&quot;">​</a></h3><p>传统的&quot;心理咨询&quot;假设&quot;改变想法 → 改变情绪 → 改变身体&quot;。但具身认知表明，这个顺序可以颠倒：<strong>改变身体 → 改变情绪 → 改变想法。</strong> 慢呼吸比&quot;告诉自己别紧张&quot;更有效（模块一），固定眼球比&quot;告诉自己别想了&quot;更有效（模块二），站桩比&quot;冥想&quot;更能快速进入副交感主导状态（模块三）。这不是&quot;身体比心理重要&quot;，而是&quot;身体是心理的快捷方式&quot;。</p><h3 id="规律三-古老实践与现代科学的趋同" tabindex="-1">规律三：古老实践与现代科学的趋同 <a class="header-anchor" href="#规律三-古老实践与现代科学的趋同" aria-label="Permalink to &quot;规律三：古老实践与现代科学的趋同&quot;">​</a></h3><p>形意拳的呼吸法（模块三）和迷走神经通路（模块一）是同一个机制的两种描述。中医的&quot;气&quot;和自主神经的节律调节是同一个现象的两种语言。禅修的&quot;观想&quot;和 scanpath 的&quot;视觉重演&quot;是同一个过程的两种解释。这提醒我们：<strong>科学不是&quot;推翻&quot;古老智慧，而是&quot;翻译&quot;古老智慧。</strong> 当一个实践被几千年的人类经验反复验证，它很可能在神经科学层面有精确的机制——只是我们还没发现。</p><hr><h2 id="四、知识边界与待探索方向" tabindex="-1">四、知识边界与待探索方向 <a class="header-anchor" href="#四、知识边界与待探索方向" aria-label="Permalink to &quot;四、知识边界与待探索方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>肠道-大脑轴（Gut-Brain Axis）</td><td>未覆盖</td><td>肠道微生物如何影响情绪、焦虑、决策</td></tr><tr><td>神经可塑性（Neuroplasticity）</td><td>部分覆盖</td><td>大脑如何在学习、创伤、康复中重组自己；习惯层见 <code>habit-reprogramming-6-steps.md</code></td></tr><tr><td>睡眠与记忆巩固</td><td>未覆盖</td><td>慢波睡眠、REM 睡眠在记忆编码和情绪调节中的角色</td></tr><tr><td>意识理论（IIT、GWT、预测加工）</td><td>未覆盖</td><td>意识从物质中涌现的数学和哲学框架</td></tr><tr><td>神经经济学</td><td>未覆盖</td><td>决策、风险偏好、社会行为的神经基础</td></tr><tr><td>神经美学</td><td>未覆盖</td><td>艺术、音乐、美的神经基础</td></tr><tr><td>疼痛神经科学</td><td>未覆盖</td><td>疼痛的神经机制和非药物干预</td></tr></tbody></table><hr><h2 id="五、相关知识" tabindex="-1">五、相关知识 <a class="header-anchor" href="#五、相关知识" aria-label="Permalink to &quot;五、相关知识&quot;">​</a></h2><ul><li><code>topics/physics/</code> — 物理极限与测量（神经信号解码本质上是物理测量问题）</li><li><code>topics/philosophy/</code> — 意识、自由意志、身心关系（神经科学的哲学地基）</li><li><code>topics/psychology/energy-management.md</code> — 能量管理（自主神经调节的日常应用）</li><li><code>topics/ai-system-architecture/</code> — AI 推理与验证（脑机接口的 AI 对应面）</li></ul><hr><h2 id="六、科学日报-神经科学板块归档" tabindex="-1">六、科学日报（神经科学板块归档） <a class="header-anchor" href="#六、科学日报-神经科学板块归档" aria-label="Permalink to &quot;六、科学日报（神经科学板块归档）&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/neuroscience/science-daily-2026-10-25-neuro.html">科学日报 2026-10-25：CD51 把星形胶质细胞分成两类功能亚型</a> — 第44期科学板块：构建 <strong>CD51-FLP 小鼠品系</strong>，在<strong>体内直接比较</strong>回路中 <strong>CD51⁺ 与 CD51⁻</strong> 星形胶质细胞——二者在<strong>皮层与海马</strong>具<strong>独特的形态、电生理与发育特性</strong>；功能上 <strong>CD51⁺ 星形胶质细胞选择性促进发育皮层的突触形成与回路可塑性</strong> → <strong>「细胞类型」正在被拆成「可寻址亚型」</strong>；方法判据：<strong>选择性标记 + 可诱导拆分品系，把「分子异质性」变成「功能分工」的因果证据</strong>（Nature, 10.1038/s41586-026-11186-z）</li><li><a href="/zhishiku-reading/topics/neuroscience/science-daily-2026-10-22-neuro.html">科学日报 2026-10-22：人类岛叶的「四分区」功能架构</a> — 87 名<strong>颅内电极</strong>受试者把<strong>电刺激 + 任务态脑电 + 细胞构筑图谱</strong>结合：背-后区（躯体拓扑的伤害/温度觉）、腹-后区（跨身体部位躯体信息）、中-前区（内脏感觉与焦虑）、前-极区（直接刺激<strong>近乎沉默</strong>，但显著性检测与行动切换时强激活）；<strong>前-极区对其它岛叶区输出强、输入弱</strong> → 认知调控疼痛与躯体感知的电生理通路（Nature, 10.1038/s41586-026-11175-2）</li><li><a href="/zhishiku-reading/topics/neuroscience/science-daily-2026-10-20.html">科学日报 2026-10-20：Airscope 1 克无线介观显微镜——清醒自由活动小鼠的全皮层成像</a> — 非球面镜把总光程压到 1/2.84，1.0 g 设备在 6 mm 视场达 4 μm/12.5 Hz，单动物无缆记录 &gt;8,500 神经元（25×）；房间尺度环境/游泳/多器官植入/多动物同录，识别社会支配相关背侧皮层模式并前瞻解码竞争结果，脑—脊同步记录给出脊髓→皮层 Granger 因果（Nature, 10.1038/s41586-026-11293-x）</li><li><a href="/zhishiku-reading/topics/neuroscience/science-daily-2026-10-13.html">科学日报 2026-10-13：LSD 的受体占据与血流效应 + FAM193B CCG 重复与 AD 风险</a> — 同步 PET–MRI 首次在人脑量化 LSD 的 5-HT2A 占据（高亲和力、全局 CBF↑、全局连接↓且与 CBF 负相关、浓度—主观呈逆时针滞后环，与裸盖菇素对比）；长读长+短读长测序发现 FAM193B 启动子 CCG 重复扩张显著升高阿尔茨海默病风险（每 10 重复 OR=2.20）（Nature Neuroscience, 10.1038/s41593-026-02462-2 / 10.1038/s41593-026-02481-z）</li><li><a href="/zhishiku-reading/topics/neuroscience/science-daily-2026-09-22.html">科学日报 2026-09-22：异源皮层 xenocortication</a> — apallial 小鼠 + 人源皮层类器官占据大部分皮层体积，生成第 5 层投射神经元，行为差异只在协调与自发组织（Nature, 10.1038/s41586-026-11032-2）</li><li><a href="/zhishiku-reading/topics/neuroscience/science-daily-2026-10-09.html">科学日报 2026-10-09：分裂吸引子——果蝇导航中心快速写入航向记忆</a> — h∆K×PFG 循环回路共享&quot;波包&quot;活动，慢循环兴奋 + 快速抑制给出持续吸引子；<strong>去抑制充当&quot;测量↔记忆&quot;的快速闸门</strong>（Nature, 10.1038/s41586-026-11144-9）</li><li><a href="/zhishiku-reading/topics/neuroscience/science-daily-2026-09-14.html">科学日报 2026-09-14：新皮层长程抑制促睡眠</a> — 睡眠回路的抑制性控制</li><li><a href="/zhishiku-reading/topics/neuroscience/science-daily-2026-09-13.html">科学日报 2026-09-13</a> — 微胶质细胞 A3R 稳定睡眠</li><li><a href="/zhishiku-reading/topics/neuroscience/science-daily-2026-09-11-platonic-brain.html">科学日报 2026-09-11：柏拉图式脑桥假说</a> — 表征几何与脑区对应</li></ul><hr><h2 id="七、视频笔记归档-行为改变" tabindex="-1">七、视频笔记归档（行为改变） <a class="header-anchor" href="#七、视频笔记归档-行为改变" aria-label="Permalink to &quot;七、视频笔记归档（行为改变）&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/neuroscience/habit-reprogramming-6-steps.html">大脑重编程：如何彻底戒掉坏习惯（六步法）</a> — 目标锁定 / 威胁建模 / 身份工程 / 环境破坏 / 正向强化 / 情绪改写；<strong>附事实边界</strong>：三脑假说属隐喻、视觉化有反例（应补 WOOP 执行意图）。与 <code>topics/psychology/</code>（意志力、能量管理）、<code>fitness</code>（训练习惯）直接相关</li><li><a href="/zhishiku-reading/topics/neuroscience/winner-effect-thalamo-prefrontal.html">胜利者效应：连赢如何重写大脑（Science 2017 及其 8 年后续）</a> — 视频说&quot;浙大 Science：连赢六次，敢赢成习惯&quot;。核实：真身 <strong>Science 2017-07-14, 357(6347):162-168, DOI 10.1126/science.aak9726</strong>（一作周亭亭，通讯<strong>胡海岚</strong>，中科院神经所 + 浙大合作），<strong>不是新研究</strong>；论文原文 <strong>光遗传激活 dmPFC → 立即赢、抑制 → 立即输</strong>（视频漏了后半句，而这才是&quot;必要且充分&quot;的因果证据）；<strong>丘脑背内侧核 MD → dmPFC</strong> 突触介导持久改变 ✅；<strong>&quot;连赢六次&quot;阈值未能核实</strong>（Science 正文不在免费全文库，摘要只写 history of winning）⚠️。视频没提的 8 年后续：<strong>Neuron 2025 性别差异</strong>（雌鼠 MDT→dmPFC LTP 减弱、dmPFC PV 中间神经元兴奋性↑，人类文献也提示女性效应更弱）、<strong>Cell Res 2026：社会地位经 dmPFC 突触强度影响 T 细胞免疫</strong>（反直觉：<strong>排名第二</strong>的小鼠免疫应答最佳）。关键纠偏：视频&quot;做六件互不相关的小事连赢六次&quot;≠论文的&quot;<strong>同一竞争</strong>中连赢六次&quot;（history of winning in the same contest），属隐喻类比；&quot;小事积累建立自信&quot;另有独立支撑（Bandura 的 mastery experience 是自我效能感最强来源）</li></ul>`,76)])])}const p=o(e,[["render",s]]);export{g as __pageData,p as default};
